            throw new IllegalArgumentException("INVALID " + paramName + ": " + value);
        }
    }

    private void validateNotBlank(String value, String paramName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException("INVALID " + paramName + ": " + value);
        }
