                long targetId = rs.getLong("id");
                String selectOthersSql = "SELECT id, name, city, balance_cents FROM customer WHERE city = ? AND id <> ? ORDER BY id";
                try (PreparedStatement ps2 = conn.prepareStatement(selectOthersSql)) {
                    ps2.setString(1, city);
