        }
        String placeholders = String.join(",", Collections.nCopies(validated.size(), "?"));
        String sql = "SELECT id, name, city, balance_cents FROM customer WHERE id IN (" + placeholders + ") ORDER BY id";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < validated.size(); i++) {
                ps.setLong(i + 1, Long.parseLong(validated.get(i)));
            }
            return fetchRows(ps);
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

