    public List<String> richerThan(String minBalanceCents) {
        validateDigits(minBalanceCents, "MINBALANCE");
        String sql = "SELECT id, name, city, balance_cents FROM customer WHERE balance_cents > ? ORDER BY id";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
