    @Override
    public List<String> sameCityAs(String id) {
        validateDigits(id, "ID");
        String selectCitySql = "SELECT id, name, city, balance_cents FROM customer WHERE id = ?";
        try (PreparedStatement ps = conn.prepareStatement(selectCitySql)) {
            ps.setLong(1, Long.parseLong(id));
            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) {
                    throw new IllegalArgumentException("UNKNOWN CUSTOMER: " + id);
                }
                String city = rs.getString("city");
                long targetId = rs.getLong("id");
                String selectOthersSql = "SELECT id, name, city, balance_cents FROM customer WHERE city = ? AND id <> ? ORDER BY id";
                try (PreparedStatement ps2 = conn.prepareStatement(selectOthersSql)) {
                    ps2.setString(1, city);
                    ps2.setLong(2, targetId);
                    return fetchRows(ps2);
                }
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

