    @Override
    public int count() {
        String sql = "SELECT COUNT(*) FROM customer";
        try (Statement st = conn.createStatement();
             ResultSet rs = st.executeQuery(sql)) {
            if (rs.next()) {
                return rs.getInt(1);
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
        return 0;
    }

    private List<String> fetchRows(PreparedStatement ps) throws SQLException {
        try (ResultSet rs = ps.executeQuery()) {
            return fetchRowsFromResultSet(rs);
        }
    }

    private List<String> fetchRowsFromResultSet(ResultSet rs) throws SQLException {
        List<String> rows = new ArrayList<>();
        while (rs.next()) {
            long id = rs.getLong("id");
            String name = rs.getString("name");
            String city = rs.getString("city");
            long balance = rs.getLong("balance_cents");
            rows.add(formatRow(id, name, city, balance));
        }
        return rows;
    }

    private List<String> fetchAllRows() {
        String sql = "SELECT id, name, city, balance_cents FROM customer ORDER BY id";
        try (Statement st = conn.createStatement();
             ResultSet rs = st.executeQuery(sql)) {
            return fetchRowsFromResultSet(rs);
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    private String formatRow(long id, String name, String city, long balance) {
        return id + "|" + name + "|" + city + "|" + balance;
    }
